import type {Task} from './types';

// Version 2: authored, bounded examples. Open language production is practice,
// never a single-string correctness test. Shared passages share evidenceGroup.
type Draft=Omit<Task,'id'|'version'>;
type Pair={left:string;right:string};
const choose=(prompt:string,answer:string,distractors:string[],hint:string,explanation:string,extra:Partial<Draft>={}):Draft=>({kind:'choice',prompt,choices:[answer,...distractors],answer,hint,explanation,...extra});
const write=(prompt:string,answer:string,hint:string,explanation:string,extra:Partial<Draft>={}):Draft=>({kind:'write',prompt,answer,hint,explanation,...extra});
const build=(prompt:string,answer:string,hint:string,extra:Partial<Draft>={}):Draft=>({kind:'build',prompt,tiles:answer.includes(' ')?answer.split(' '):answer.split(''),answer,hint,explanation:`En løsning er «${answer}».`,...extra});
const order=(prompt:string,tiles:string[],hint:string,extra:Partial<Draft>={}):Draft=>({kind:'order',prompt,tiles,answer:JSON.stringify(tiles),hint,explanation:`Rekkefølgen er: ${tiles.join(' → ')}.`,...extra});
const match=(prompt:string,pairs:Pair[],hint:string,extra:Partial<Draft>={}):Draft=>({kind:'match',prompt,pairs,answer:JSON.stringify(pairs.map(p=>p.right)),hint,explanation:pairs.map(p=>`${p.left} → ${p.right}`).join('. ')+'.',...extra});
const select=(prompt:string,choices:string[],correct:string[],hint:string,explanation:string,extra:Partial<Draft>={}):Draft=>({kind:'select',prompt,choices,answer:JSON.stringify(correct),hint,explanation,...extra});
const practice=(prompt:string,hint:string,text?:string,extra:Partial<Draft>={}):Draft=>({kind:'open',prompt,hint,explanation:'Dette er øving. Fortell, skriv eller vis svaret til en voksen. Flere løsninger kan være gode.',text,...extra});

type Story={title:string;text:string;question:string;answer:string;wrong:string[];hint:string;detail:string;detailAnswer:string;detailWrong:string[];events:string[];evidence?:string};
